function draw_line(array){

	for(let i= 0; i<array.length-1; i++){

		let obj = array[i];
		let obj2 = array[i+1];

		let v = createVector(obj.x-obj2.x,obj.y-obj2.y);

		v.rotate(PI/2);
		v.mult(i/10)

		stroke(50);
		line(obj.x,obj.y,obj.x+v.x,obj.y+v.y);
		line(obj.x,obj.y,obj2.x,obj2.y);
		fill(0)
		circle(obj.x+v.x,obj.y+v.y,10);
