let pos = [];
const segNum = 160;
const segLength = 10;

function setup() {
  createCanvas(windowWidth, windowHeight);
  stroke(0, 100);
  strokeWeight(2);
  for (let i = 0; i < segNum; i++) {
    pos.push({ x: 0, y: 0 });
  }
}

function draw() {
  background(255);

  let parent = { x: (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), y: (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) };
  for (let child of pos) {
    let angle = atan2(child.y - parent.y, child.x - parent.x);
    child.x = parent.x + cos(angle) * segLength;
    child.y = parent.y + sin(angle) * segLength;
    line(parent.x, parent.y, child.x, child.y);
    parent = child;
  }
	draw_line(pos)
}
